insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  'b04c0ad3-113a-4690-8a26-ff0b1de9d28a', 'rajgad-fort-trek', 'Rajgad Fort Trek', 'Gunjavane, near Pune', 'Sahyadri – Pune', array['weekend-treks','fort-treks']::text[], 1, '1 day', 'Moderate', '1,376 m', 'About 10 km round trip', 'June to February', 'Climb to the fort that was Chhatrapati Shivaji Maharaj''s capital for 26 years, with views of Torna across the valley.', 'Rajgad is one of the largest and best-preserved forts in the Sahyadris. We climb from Gunjavane village through forest and open ridges to Padmavati machi, explore Suvela and Sanjeevani machis, and look across to Torna fort on a clear day.

The trail has a few steep rock patches with railings, so it''s a good next step after your first easy trek.',
  '["Padmavati lake and temple","Balekilla — the fort''s highest point","Sanjeevani and Suvela machis with their double walls","Views of Torna fort across the valley"]'::jsonb, '[{"label":"Day 1","title":"Pune → Rajgad → Pune","points":["5:30 am – Pickup from Pune","8:00 am – Breakfast at Gunjavane village, introductions and safety briefing","8:45 am – Start the climb (2.5–3 hours)","12:00 pm – Explore Padmavati machi and Balekilla","2:00 pm – Start descent","4:30 pm – Late lunch in the village","8:30 pm – Drop back in Pune"]}]'::jsonb, '["Travel by tempo traveller from the chosen pickup point","Breakfast and lunch (vegetarian)","Experienced trek leaders","First aid kit","Forest and entry fees"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control"]'::jsonb, '["2 litres of water","Trekking shoes with good grip (no sports/running shoes with flat soles)","Small backpack (20–30 L)","Snacks: dry fruits, chikki, energy bars","Cap, sunglasses and sunscreen","Raincoat or poncho (June–September)","Extra pair of clothes and a plastic bag for wet clothes","Original photo ID","Personal medicines"]'::jsonb, 'You should be able to walk 8–10 km and climb stairs for 30 minutes without stopping. Some short rock patches need using your hands.', '[{"city":"Pune","place":"[Pickup spot, e.g. Swargate / Shivajinagar]","time":"5:30 am","mapsUrl":"https://maps.google.com/?q=Swargate+Pune"},{"city":"Mumbai","place":"[Pickup spot, e.g. Dadar East]","time":"11:30 pm (previous night)","mapsUrl":"https://maps.google.com/?q=Dadar+East"},{"city":"Base Village","place":"Gunjavane village","time":"8:00 am","mapsUrl":"https://maps.google.com/?q=Gunjavane"}]'::jsonb, '[{"pickup":"Pune","price":1199},{"pickup":"Mumbai","price":1699},{"pickup":"Base Village","price":799}]'::jsonb, '[]'::jsonb,
  'full', 0, '{"minPeople":5,"percent":5}'::jsonb, '["/images/trips/rajgad-fort-trek-1.svg","/images/trips/rajgad-fort-trek-2.svg","/images/trips/rajgad-fort-trek-3.svg"]'::jsonb, array['23707424-fd47-4f9b-9de8-eccb44a6b841','cffd28e9-ddcf-4198-b621-8e4d61b2233b']::uuid[], '[{"q":"Is Rajgad OK for a first-time trekker?","a":"If you''re reasonably active, yes. The climb is long and has a few rocky patches, so take your time and the leaders will help."},{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 95, true, 1
) on conflict (slug) do nothing;
