insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  'ec387f66-255a-4608-8102-0d03a940ece8', 'harishchandragad-trek', 'Harishchandragad Trek', 'Khireshwar, Ahilyanagar district', 'Sahyadri – Malshej', array['weekend-treks','fort-treks']::text[], 2, '2 days / 1 night', 'Moderate', '1,424 m', 'About 14 km over 2 days', 'August to February', 'Watch the sunset from Konkan Kada, sleep under the stars on top, and see the ancient Kedareshwar cave temple.', 'Harishchandragad is a Sahyadri favourite for good reason. We climb through Tolar Khind from Khireshwar, camp on top, watch the sunset from the curved cliff of Konkan Kada, and wake up early for sunrise from Taramati peak.

On the way you''ll see the Harishchandreshwar temple, carved from a single rock, and the Kedareshwar cave with its Shivling surrounded by water.',
  '["Sunset from the overhanging cliff of Konkan Kada","Kedareshwar cave temple","Sunrise from Taramati peak","Night under the stars in tents"]'::jsonb, '[{"label":"Day 0","title":"Overnight travel","points":["11:30 pm – Pickup from Pune / Mumbai","Overnight drive to Khireshwar village"]},{"label":"Day 1","title":"Climb and Konkan Kada sunset","points":["6:00 am – Reach Khireshwar, freshen up, breakfast","7:30 am – Start the climb via Tolar Khind (4–5 hours)","1:00 pm – Lunch on top, set up tents","Afternoon – Harishchandreshwar temple and Kedareshwar cave","5:30 pm – Sunset at Konkan Kada","8:30 pm – Dinner and stargazing"]},{"label":"Day 2","title":"Taramati sunrise and descent","points":["5:30 am – Climb Taramati peak for sunrise","8:00 am – Breakfast, pack up","9:00 am – Descend to Khireshwar","1:00 pm – Lunch and drive back","8:00 pm – Drop in Pune / Mumbai"]}]'::jsonb, '["Travel by tempo traveller / bus from the chosen pickup point","Breakfast, lunch and dinner on Day 1; breakfast and lunch on Day 2","Tent stay on top (sharing as selected)","Experienced trek leaders and local guide","First aid kit","Forest and entry fees"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control"]'::jsonb, '["2 litres of water","Trekking shoes with good grip (no sports/running shoes with flat soles)","Small backpack (20–30 L)","Snacks: dry fruits, chikki, energy bars","Cap, sunglasses and sunscreen","Torch or headlamp with extra batteries","Light jacket or fleece (it gets cold at night)","Sleeping mat or light sleeping bag (if not renting)","Original photo ID","Personal medicines"]'::jsonb, 'You should be comfortable walking 5–6 hours with a backpack. Previous trekking experience helps but isn''t required.', '[{"city":"Pune","place":"[Pickup spot, e.g. Shivajinagar]","time":"11:30 pm (previous night)"},{"city":"Mumbai","place":"[Pickup spot, e.g. Kalyan station]","time":"11:59 pm (previous night)"},{"city":"Base Village","place":"Khireshwar village","time":"6:00 am","mapsUrl":"https://maps.google.com/?q=Khireshwar"}]'::jsonb, '[{"pickup":"Pune","price":2299},{"pickup":"Mumbai","price":2499},{"pickup":"Base Village","price":1599}]'::jsonb, '[{"name":"Shared tent (3–4 people)","extra":0},{"name":"Twin sharing tent","extra":400}]'::jsonb,
  'advance', 1000, '{"minPeople":5,"percent":5}'::jsonb, '["/images/trips/harishchandragad-trek-1.svg","/images/trips/harishchandragad-trek-2.svg","/images/trips/harishchandragad-trek-3.svg"]'::jsonb, array['23707424-fd47-4f9b-9de8-eccb44a6b841','cffd28e9-ddcf-4198-b621-8e4d61b2233b']::uuid[], '[{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 90, true, 2
) on conflict (slug) do nothing;
