insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  'db525683-c8c2-4014-aa7d-af25dfea82d3', 'kalsubai-night-trek', 'Kalsubai Night Trek', 'Bari village, Igatpuri', 'Sahyadri – Nashik', array['night-treks','weekend-treks']::text[], 2, 'Overnight', 'Moderate', '1,646 m', 'About 11 km round trip', 'October to February', 'Trek through the night to the highest point in Maharashtra and watch the sunrise above the clouds.', 'Kalsubai is the highest peak in Maharashtra. We start from Bari village late at night, climb with headlamps through farms, steps and iron ladders, and reach the summit temple before sunrise.

On a clear morning you can see Bhandardara lake, Alang–Madan–Kulang and Ratangad from the top.',
  '["Sunrise from Maharashtra''s highest peak","Iron ladders on the final section","Kalsubai temple at the summit","Views of Bhandardara lake and the AMK range"]'::jsonb, '[{"label":"Night","title":"Travel and night climb","points":["9:30 pm – Pickup from Pune / Mumbai","1:30 am – Reach Bari village, tea and safety briefing","2:00 am – Start the night climb (3.5–4 hours)"]},{"label":"Morning","title":"Summit sunrise and return","points":["6:15 am – Sunrise at the summit","7:30 am – Start descent","10:00 am – Breakfast in Bari village","2:00 pm – Drop in Pune / Mumbai"]}]'::jsonb, '["Travel by tempo traveller from the chosen pickup point","Tea on arrival and breakfast after the trek","Experienced trek leaders","First aid kit","Entry fees"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control"]'::jsonb, '["2 litres of water","Trekking shoes with good grip (no sports/running shoes with flat soles)","Small backpack (20–30 L)","Snacks: dry fruits, chikki, energy bars","Cap, sunglasses and sunscreen","Torch or headlamp with extra batteries","Light jacket or fleece (it gets cold at night)","Sleeping mat or light sleeping bag (if not renting)","Original photo ID","Personal medicines"]'::jsonb, 'The climb is steady and long. You should be able to walk uphill for 3–4 hours with short breaks. Not recommended if you have a fear of heights on ladders.', '[{"city":"Pune","place":"[Pickup spot, e.g. Nashik Phata]","time":"9:30 pm"},{"city":"Mumbai","place":"[Pickup spot, e.g. Thane station]","time":"10:30 pm"},{"city":"Base Village","place":"Bari village","time":"1:30 am","mapsUrl":"https://maps.google.com/?q=Bari+Kalsubai"}]'::jsonb, '[{"pickup":"Pune","price":1499},{"pickup":"Mumbai","price":1399},{"pickup":"Base Village","price":899}]'::jsonb, '[]'::jsonb,
  'full', 0, '{"minPeople":5,"percent":5}'::jsonb, '["/images/trips/kalsubai-night-trek-1.svg","/images/trips/kalsubai-night-trek-2.svg","/images/trips/kalsubai-night-trek-3.svg"]'::jsonb, array['cffd28e9-ddcf-4198-b621-8e4d61b2233b']::uuid[], '[{"q":"Is a night trek safe?","a":"Yes, with the right group. Our leaders walk at the front and back, everyone carries a headlamp, and we take a well-used route with regular breaks."},{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 88, true, 3
) on conflict (slug) do nothing;
