insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  'abb205f9-9d18-49ec-b8a5-387cd6a532ed', 'andharban-jungle-trek', 'Andharban Jungle Trek', 'Pimpri village, Tamhini Ghat', 'Sahyadri – Tamhini', array['monsoon-treks','weekend-treks']::text[], 1, '1 day', 'Easy', 'About 650 m', 'About 13 km (mostly downhill)', 'June to September (also beautiful till December)', 'A long, gentle walk through thick forest on the edge of the Sahyadris, past streams and waterfalls.', 'Andharban means ''dark forest''. The trail runs from Pimpri village near Tamhini Ghat down to Bhira, through dense forest that stays green and shaded for most of the way.

It''s long but mostly downhill, with valley views, small streams to cross and waterfalls during the monsoon. A great first trek for anyone who can walk comfortably for a few hours.',
  '["Dense forest trail with valley viewpoints","Waterfalls and stream crossings in the monsoon","View of the Kundalika valley","Easy pace, good for first-timers"]'::jsonb, '[{"label":"Day 1","title":"Pune → Andharban → Pune","points":["5:30 am – Pickup from Pune","8:00 am – Breakfast near Tamhini, safety briefing","9:00 am – Start the trail from Pimpri village (5–6 hours)","3:00 pm – Reach Bhira, lunch","4:30 pm – Drive back","8:00 pm – Drop in Pune"]}]'::jsonb, '["Travel by tempo traveller from the chosen pickup point","Breakfast and lunch (vegetarian)","Experienced trek leaders","First aid kit","Forest permission and entry fees"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control"]'::jsonb, '["2 litres of water","Trekking shoes with good grip (no sports/running shoes with flat soles)","Small backpack (20–30 L)","Snacks: dry fruits, chikki, energy bars","Cap, sunglasses and sunscreen","Raincoat or poncho (June–September)","Extra pair of clothes and a plastic bag for wet clothes","Original photo ID","Personal medicines"]'::jsonb, 'Easy, but long. You should be able to walk 12–13 km at an easy pace.', '[{"city":"Pune","place":"[Pickup spot, e.g. Chandni Chowk]","time":"5:30 am"},{"city":"Mumbai","place":"[Pickup spot, e.g. Dadar East]","time":"1:30 am"},{"city":"Base Village","place":"Pimpri village","time":"8:30 am","mapsUrl":"https://maps.google.com/?q=Pimpri+Tamhini"}]'::jsonb, '[{"pickup":"Pune","price":1399},{"pickup":"Mumbai","price":1799},{"pickup":"Base Village","price":999}]'::jsonb, '[]'::jsonb,
  'full', 0, '{"minPeople":5,"percent":5}'::jsonb, '["/images/trips/andharban-jungle-trek-1.svg","/images/trips/andharban-jungle-trek-2.svg","/images/trips/andharban-jungle-trek-3.svg"]'::jsonb, array['23707424-fd47-4f9b-9de8-eccb44a6b841']::uuid[], '[{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 80, true, 4
) on conflict (slug) do nothing;
