insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  '742a222e-54e2-4f81-8b15-f3e2bbe559a5', 'pawna-lake-camping', 'Pawna Lake Camping', 'Pawna Lake, near Lonavala', 'Sahyadri – Lonavala', array['camping','corporate-trips']::text[], 2, '2 days / 1 night', 'Easy', 'About 600 m', 'No trekking', 'All year (best October to March)', 'Lakeside tents, a bonfire, barbecue and music, with Tung, Tikona and Lohagad around you.', 'An easy overnight escape for friends, couples, families and teams. We camp on the banks of Pawna Lake with forts on the skyline, light a bonfire, put on some music and have dinner by the water.

Wake up to sunrise over the lake and an unhurried breakfast before heading home.',
  '["Lakeside tents","Bonfire, music and barbecue","Views of Tung, Tikona and Lohagad forts","Sunrise over the lake"]'::jsonb, '[{"label":"Day 1","title":"Arrive and set up camp","points":["2:00 pm – Pickup from Pune / Mumbai","5:00 pm – Check in, tea and snacks","6:00 pm – Sunset by the lake, games","7:30 pm – Bonfire, music and barbecue","9:00 pm – Dinner"]},{"label":"Day 2","title":"Sunrise and head home","points":["6:30 am – Sunrise by the lake","8:30 am – Breakfast","10:00 am – Check out and drive back","1:00 pm – Drop in Pune / Mumbai"]}]'::jsonb, '["Travel from the chosen pickup point (not for Base Village)","Tent stay with mattresses (sharing as selected)","Evening snacks, barbecue (veg / non-veg), dinner and breakfast","Bonfire and music","Washrooms at the campsite","Camp coordinator"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control"]'::jsonb, '["Light jacket for the night","Torch","Comfortable shoes or sandals","Toiletries and towel","Original photo ID","Personal medicines"]'::jsonb, 'No fitness requirement. Suitable for all ages.', '[{"city":"Pune","place":"[Pickup spot, e.g. Wakad Bridge]","time":"2:00 pm"},{"city":"Mumbai","place":"[Pickup spot, e.g. Vashi]","time":"1:00 pm"},{"city":"Base Village","place":"Campsite, Pawna Lake","time":"5:00 pm (self-reach)","mapsUrl":"https://maps.google.com/?q=Pawna+Lake"}]'::jsonb, '[{"pickup":"Pune","price":1799},{"pickup":"Mumbai","price":2199},{"pickup":"Base Village","price":1299}]'::jsonb, '[{"name":"Triple sharing tent","extra":0},{"name":"Twin sharing tent","extra":300}]'::jsonb,
  'advance', 500, '{"minPeople":6,"percent":8}'::jsonb, '["/images/trips/pawna-lake-camping-1.svg","/images/trips/pawna-lake-camping-2.svg","/images/trips/pawna-lake-camping-3.svg"]'::jsonb, array['cffd28e9-ddcf-4198-b621-8e4d61b2233b']::uuid[], '[{"q":"Can we bring kids?","a":"Yes. Kids above 5 years are welcome. Children under 5 come free when sharing a tent with parents."},{"q":"Can we book the whole campsite for a team?","a":"Yes. Use the Plan a Custom Trip form or message us on WhatsApp for team and corporate bookings."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 92, true, 5
) on conflict (slug) do nothing;
