insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  '22e5831b-edb7-4c22-8b21-e6bfb44dc4a2', 'hampi-backpacking-trip', 'Hampi Backpacking Trip', 'Hampi, Karnataka', 'Karnataka', array['backpacking']::text[], 4, '4 days / 3 nights', 'Easy', 'About 470 m', 'Walking and cycling, 5–8 km a day', 'October to February', 'Boulder hills, ruined temples and coracle rides on the Tungabhadra — Hampi at backpacker pace with a fun group.', 'Hampi was the capital of the Vijayanagara Empire, and its ruins are spread across a landscape of giant boulders, banana fields and river. We explore on foot and by bicycle, catch sunrise and sunset from the hills, and cross to the quieter Hampi Island side.

Stays are in simple, clean guesthouses, and the group travels together from Pune by overnight sleeper bus.',
  '["Virupaksha temple and Hampi Bazaar","Stone chariot at Vittala temple","Sunset from Hemakuta hill, sunrise from Matanga hill","Coracle ride on the Tungabhadra river","Cycling around Anegundi and Sanapur lake"]'::jsonb, '[{"label":"Day 0","title":"Overnight bus","points":["7:00 pm – Depart Pune by sleeper bus"]},{"label":"Day 1","title":"Hampi Bazaar and Hemakuta sunset","points":["7:00 am – Reach Hampi, check in, breakfast","Virupaksha temple and Hampi Bazaar","Evening – Sunset from Hemakuta hill"]},{"label":"Day 2","title":"Royal ruins by bicycle","points":["Vittala temple and the stone chariot","Lotus Mahal, Elephant Stables, Queen''s Bath","Coracle ride on the Tungabhadra"]},{"label":"Day 3","title":"Hampi Island and Anegundi","points":["5:30 am – Sunrise from Matanga hill","Cross to Hampi Island, cycle to Sanapur lake and Anegundi","8:00 pm – Board the bus back to Pune"]},{"label":"Day 4","title":"Arrive in Pune","points":["8:00 am – Reach Pune"]}]'::jsonb, '["Sleeper bus from Pune / Mumbai and back (not for Base Village)","3 nights'' stay in guesthouses (sharing as selected)","Breakfast and dinner on all days","Bicycle hire for 2 days","Coracle ride","Trip leader throughout"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control","Monument entry tickets (about ₹40 per site)","Lunch on all days"]'::jsonb, '["Backpack (40–50 L)","Comfortable walking shoes and sandals","Cap, sunglasses and sunscreen","Water bottle","Light cotton clothes and one warm layer","Original photo ID","Personal medicines"]'::jsonb, 'Easy. You''ll walk and cycle 5–8 km a day in the sun, with breaks.', '[{"city":"Pune","place":"[Bus pickup, e.g. Swargate]","time":"7:00 pm (Day 0)"},{"city":"Mumbai","place":"[Bus pickup, e.g. Sion]","time":"3:00 pm (Day 0)"},{"city":"Base Village","place":"Hampi Bus Stand","time":"8:00 am (Day 1)","mapsUrl":"https://maps.google.com/?q=Hampi+Bus+Stand"}]'::jsonb, '[{"pickup":"Pune","price":8999},{"pickup":"Mumbai","price":9499},{"pickup":"Base Village","price":5999}]'::jsonb, '[{"name":"Triple sharing room","extra":0},{"name":"Twin sharing room","extra":1000}]'::jsonb,
  'advance', 3000, '{"minPeople":4,"percent":5}'::jsonb, '["/images/trips/hampi-backpacking-trip-1.svg","/images/trips/hampi-backpacking-trip-2.svg","/images/trips/hampi-backpacking-trip-3.svg"]'::jsonb, array['23707424-fd47-4f9b-9de8-eccb44a6b841']::uuid[], '[{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 85, true, 6
) on conflict (slug) do nothing;
