insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  '3a636b5f-77bb-482e-b57f-b31d4c8bf47c', 'gokarna-beach-trek', 'Gokarna Beach Trek', 'Gokarna, Karnataka', 'Karnataka', array['backpacking']::text[], 3, '3 days / 2 nights', 'Easy', 'Sea level', 'About 9 km beach-to-beach trail', 'October to March', 'Walk the cliffs from Kudle to Paradise beach, swim, and end each day with a sunset over the Arabian Sea.', 'Gokarna is the relaxed alternative to Goa. The beach trek follows rocky headlands and forest paths from Kudle beach to Om, Half Moon and Paradise beaches, with plenty of time to swim and rest on the way.

We stay near Kudle beach, so sunsets and evenings by the sea are part of every day.',
  '["Beach trek: Kudle → Om → Half Moon → Paradise","Boat ride back from Paradise beach","Sunsets on Kudle beach","Mahabaleshwar temple and Gokarna town"]'::jsonb, '[{"label":"Day 0","title":"Overnight bus","points":["6:30 pm – Depart Pune by sleeper bus"]},{"label":"Day 1","title":"Arrive and settle in","points":["9:00 am – Reach Gokarna, check in near Kudle beach","Afternoon – Gokarna town and Mahabaleshwar temple","Evening – Sunset at Kudle beach"]},{"label":"Day 2","title":"The beach trek","points":["8:00 am – Start the trail to Om, Half Moon and Paradise beaches","Swim and relax at Paradise beach","4:00 pm – Boat back to Gokarna"]},{"label":"Day 3","title":"Slow morning and head home","points":["Free morning on the beach","1:00 pm – Check out","6:00 pm – Board the bus back","Arrive Pune next morning"]}]'::jsonb, '["Sleeper bus from Pune / Mumbai and back (not for Base Village)","2 nights'' stay in beach huts or guesthouse (sharing as selected)","Breakfast and dinner on all days","Boat ride from Paradise beach","Trip leader throughout"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control","Lunch on all days","Water sports"]'::jsonb, '["Backpack (30–40 L)","Sandals or shoes with grip for rocky sections","Swimwear and quick-dry towel","Cap, sunglasses and sunscreen","Water bottle","Original photo ID","Personal medicines"]'::jsonb, 'Easy. The beach trail has some rocky climbs, about 4–5 hours with breaks.', '[{"city":"Pune","place":"[Bus pickup, e.g. Swargate]","time":"6:30 pm (Day 0)"},{"city":"Mumbai","place":"[Bus pickup, e.g. Sion]","time":"3:00 pm (Day 0)"},{"city":"Base Village","place":"Gokarna Bus Stand","time":"9:00 am (Day 1)","mapsUrl":"https://maps.google.com/?q=Gokarna+Bus+Stand"}]'::jsonb, '[{"pickup":"Pune","price":6999},{"pickup":"Mumbai","price":7499},{"pickup":"Base Village","price":4499}]'::jsonb, '[{"name":"Triple sharing hut","extra":0},{"name":"Twin sharing hut","extra":800}]'::jsonb,
  'advance', 2500, '{"minPeople":4,"percent":5}'::jsonb, '["/images/trips/gokarna-beach-trek-1.svg","/images/trips/gokarna-beach-trek-2.svg","/images/trips/gokarna-beach-trek-3.svg"]'::jsonb, array['cffd28e9-ddcf-4198-b621-8e4d61b2233b']::uuid[], '[{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 82, true, 7
) on conflict (slug) do nothing;
