insert into trips (id, slug, name, location, region, categories, duration_days, duration_label, difficulty, altitude, distance, best_season, short_description, overview, highlights, itinerary, inclusions, exclusions, things_to_carry, fitness, meeting_points, pickup_prices, stay_options, payment_mode, advance_amount, group_discount, images, leader_ids, faqs, popularity, is_published, sort_order) values (
  '58fa150a-024d-42bf-b81d-751e71abd2ea', 'kedarkantha-himalayan-trek', 'Kedarkantha Himalayan Trek', 'Sankri, Uttarakhand', 'Himalayas – Uttarakhand', array['himalayan-treks']::text[], 6, '6 days / 5 nights', 'Moderate', '3,800 m (12,500 ft)', 'About 20 km on trail', 'December to April (snow trek)', 'The classic first Himalayan snow trek — pine forests, frozen lakes and a summit sunrise above 12,000 ft.', 'Kedarkantha is often the first Himalayan summit for trekkers from Maharashtra. The trail climbs from Sankri village through pine and oak forest to campsites in snowy clearings, with the summit push starting well before dawn.

From the top you''ll see Swargarohini, Bandarpoonch and Black Peak. Our Himalayan team handles camps, meals and safety, and the group meets in Dehradun.',
  '["Summit sunrise at 3,800 m","Snow campsites at Juda ka Talab and Kedarkantha base","Views of Swargarohini, Bandarpoonch and Black Peak","Sankri village and Govind wildlife area"]'::jsonb, '[{"label":"Day 1","title":"Dehradun → Sankri","points":["6:30 am – Pickup from Dehradun","Drive 8–9 hours to Sankri (1,950 m)","Evening – Briefing and gear check"]},{"label":"Day 2","title":"Sankri → Juda ka Talab","points":["Trek 4–5 hours through pine forest","Camp near the lake (2,700 m)"]},{"label":"Day 3","title":"Juda ka Talab → Base camp","points":["Trek 3–4 hours to Kedarkantha base (3,400 m)","Acclimatisation walk"]},{"label":"Day 4","title":"Summit day","points":["3:00 am – Start the summit climb","Sunrise at the summit (3,800 m)","Descend to Hargaon camp"]},{"label":"Day 5","title":"Hargaon → Sankri","points":["Trek down 3–4 hours","Celebration dinner in Sankri"]},{"label":"Day 6","title":"Sankri → Dehradun","points":["7:00 am – Drive back","Reach Dehradun by 6:00 pm"]}]'::jsonb, '["Pune / Mumbai option: 3AC train tickets to Dehradun and back","Dehradun – Sankri – Dehradun transport","Stay in guesthouse at Sankri and tents on the trek (triple sharing)","All meals from Day 1 dinner to Day 6 breakfast","Certified Himalayan trek leader, guides, cook and support staff","Forest permits and camping fees","Microspikes and gaiters","First aid, oxygen cylinder and oximeter"]'::jsonb, '["Anything not mentioned in inclusions","Personal expenses: snacks, drinks, tips","Food on the way during travel","Costs due to bad weather, road blocks or other events outside our control","Porter to carry your backpack (about ₹1,800)","Travel insurance"]'::jsonb, '["Backpack (50–60 L) with rain cover","Trekking shoes with ankle support","3 warm layers including a down/padded jacket","Thermals, woollen cap, gloves and socks","Sunglasses (UV protection)","2 water bottles","Headlamp","Medical certificate (form shared after booking)","Original photo ID"]'::jsonb, 'You should be able to jog 5 km in under 40 minutes before the trek. We''ll share a 6-week fitness plan after you book.', '[{"city":"Pune","place":"Pune railway station (train to Dehradun)","time":"[Train time shared after booking]"},{"city":"Dehradun","place":"Dehradun railway station","time":"6:30 am (Day 1)","mapsUrl":"https://maps.google.com/?q=Dehradun+Railway+Station"},{"city":"Base Village","place":"Sankri village","time":"5:00 pm (Day 1)","mapsUrl":"https://maps.google.com/?q=Sankri"}]'::jsonb, '[{"pickup":"Pune","price":15999},{"pickup":"Dehradun","price":8999},{"pickup":"Base Village","price":7999}]'::jsonb, '[]'::jsonb,
  'advance', 3000, '{"minPeople":4,"percent":5}'::jsonb, '["/images/trips/kedarkantha-himalayan-trek-1.svg","/images/trips/kedarkantha-himalayan-trek-2.svg","/images/trips/kedarkantha-himalayan-trek-3.svg"]'::jsonb, array['52090edc-5370-4ff0-aeaa-45e8bdf2e6fc']::uuid[], '[{"q":"I''ve never done a Himalayan trek. Can I do Kedarkantha?","a":"Yes, if you prepare. Many people do Kedarkantha as their first Himalayan trek. Follow the fitness plan we send and you''ll enjoy it."},{"q":"How cold does it get?","a":"Daytime is usually 5–10°C and nights can drop to –5 to –10°C at higher camps. Our tents and sleeping bags are rated for these temperatures."},{"q":"Can I join this trip alone?","a":"Yes. Most of our groups have several solo travellers. You''ll be added to the trip WhatsApp group a few days before departure so you can say hello before you meet."},{"q":"Is it safe for women travellers?","a":"Yes. Our groups usually include women travellers and we try to have at least one woman coordinator on every trip. Stays are arranged with separate sharing for women on request."},{"q":"What happens if the trip is cancelled due to weather?","a":"If we cancel a trip for safety reasons, you can move to another date or get a full credit for a future trip."}]'::jsonb, 87, true, 8
) on conflict (slug) do nothing;
